#ifndef SCAMPTRIE_BASE_H
#define SCAMPTRIE_BASE_H

// Shared constants, 128-bit prefix primitives and a software prefix trie.
// Everything here is header-only so every translation unit agrees on it.

#include <cstdint>
#include <vector>

typedef uint64_t nexthop_t;

// Sentinel for "no matching prefix" in lookup results.
static constexpr nexthop_t LPM_INVALID_NH = static_cast<nexthop_t>(-1);
// 22-bit forwarding value that encodes a null BMP inside packed records.
static constexpr uint32_t HOP_NULL = 4194303u;
// The only legal "absent" child32 record (stage 15, key 0, cell 0).
static constexpr uint32_t CHILD_ABSENT = 15u << 6;

static constexpr int RAM_NUM = 11;          // number of pipeline stages (0..10)
static constexpr int MAX_FIB_ENTRIES = 8192;

#define SCAMPTRIE_OK 0
#define SCAMPTRIE_FAIL 1

struct ip6_t {
    uint64_t hi = 0;
    uint64_t lo = 0;
};

inline bool operator==(const ip6_t& a, const ip6_t& b) { return a.hi == b.hi && a.lo == b.lo; }
inline bool operator!=(const ip6_t& a, const ip6_t& b) { return !(a == b); }

// A normalized FIB prefix together with its forwarding hop.
struct PrefixRec {
    ip6_t addr;
    uint8_t len = 0;
    uint32_t hop = 0;
};

inline bool operator<(const PrefixRec& a, const PrefixRec& b) {
    if (a.addr.hi != b.addr.hi) return a.addr.hi < b.addr.hi;
    if (a.addr.lo != b.addr.lo) return a.addr.lo < b.addr.lo;
    return a.len < b.len;
}
inline bool operator==(const PrefixRec& a, const PrefixRec& b) {
    return a.addr == b.addr && a.len == b.len && a.hop == b.hop;
}

// ---- 64-bit helpers -------------------------------------------------------

// Keep only the top n bits of a 64-bit word (n in 0..64).
inline uint64_t keep_top(uint64_t v, int n) {
    if (n <= 0) return 0;
    if (n >= 64) return v;
    return (v >> (64 - n)) << (64 - n);
}

// Mask of the low n bits (n in 0..64).
inline uint64_t low_mask(int n) {
    if (n <= 0) return 0;
    if (n >= 64) return ~0ULL;
    return (1ULL << n) - 1ULL;
}

inline int popcnt64(uint64_t v) { return __builtin_popcountll(v); }

// ---- 128-bit helpers -----------------------------------------------------

// Clear all host bits so that a holds only its first len bits.
inline void mask_prefix(ip6_t& a, int len) {
    if (len <= 0) { a.hi = 0; a.lo = 0; return; }
    if (len <= 64) { a.hi = keep_top(a.hi, len); a.lo = 0; return; }
    a.lo = keep_top(a.lo, len - 64);
}

// True when the normalized prefix (p,plen) covers address a.
inline bool prefix_of(const ip6_t& p, int plen, const ip6_t& a) {
    if (plen <= 0) return true;
    if (plen <= 64) return keep_top(a.hi, plen) == keep_top(p.hi, plen);
    if (a.hi != p.hi) return false;
    return keep_top(a.lo, plen - 64) == keep_top(p.lo, plen - 64);
}

// Extract the n bits of a starting at bit offset d (bit 0 is the MSB).
// Callers only need n <= 64.
inline uint64_t get_bits(const ip6_t& a, int d, int n) {
    if (n <= 0) return 0;
    if (n > 64) n = 64;
    if (d + n <= 64) return (a.hi >> (64 - d - n)) & low_mask(n);
    if (d >= 64) return (a.lo >> (128 - d - n)) & low_mask(n);
    int hn = 64 - d;
    int ln = n - hn;
    uint64_t hi_part = a.hi & low_mask(hn);
    uint64_t lo_part = (a.lo >> (64 - ln)) & low_mask(ln);
    return (hi_part << ln) | lo_part;
}

// OR the n-bit value v into a at bit offset d (target bits must be zero).
inline void or_bits(ip6_t& a, int d, uint64_t v, int n) {
    if (n <= 0) return;
    v &= low_mask(n);
    if (d + n <= 64) { a.hi |= v << (64 - d - n); return; }
    if (d >= 64) { a.lo |= v << (128 - d - n); return; }
    int hn = 64 - d;
    int ln = n - hn;
    a.hi |= (v >> ln) & low_mask(hn);
    a.lo |= (v & low_mask(ln)) << (64 - ln);
}

// ---- software prefix trie ------------------------------------------------

// Uncompressed binary trie over normalized prefixes.  Supports last-write-wins
// updates and longest-prefix lookups bounded by a maximum length (used both by
// the live FIB and by the independent BMP recomputation of a packed image).
class PrefixTrie {
public:
    PrefixTrie() { nodes_.resize(1); }

    void clear() {
        nodes_.clear();
        nodes_.resize(1);
        entries_.clear();
    }

    // Insert or update a prefix; returns true when a new prefix was added.
    bool insert(const ip6_t& p, int len, uint32_t hop) {
        ip6_t m = p;
        mask_prefix(m, len);
        uint32_t cur = 0;
        for (int i = 0; i < len; ++i) {
            uint32_t b = bit_at(m, i);
            uint32_t nx = nodes_[cur].c[b];
            if (nx == 0) {
                nx = static_cast<uint32_t>(nodes_.size());
                nodes_.emplace_back();
                nodes_[cur].c[b] = nx;
            }
            cur = nx;
        }
        int32_t e = nodes_[cur].entry;
        if (e < 0) {
            PrefixRec r;
            r.addr = m;
            r.len = static_cast<uint8_t>(len);
            r.hop = hop;
            nodes_[cur].entry = static_cast<int32_t>(entries_.size());
            entries_.push_back(r);
            return true;
        }
        entries_[static_cast<size_t>(e)].hop = hop;
        return false;
    }

    // Hop of the longest prefix of length <= max_len that matches a, or -1.
    int32_t longest_match(const ip6_t& a, int max_len) const {
        int32_t best = nodes_[0].entry;
        uint32_t cur = 0;
        for (int i = 0; i < max_len; ++i) {
            uint32_t b = bit_at(a, i);
            uint32_t nx = nodes_[cur].c[b];
            if (nx == 0) break;
            cur = nx;
            if (nodes_[cur].entry >= 0) best = nodes_[cur].entry;
        }
        if (best < 0) return -1;
        return static_cast<int32_t>(entries_[static_cast<size_t>(best)].hop);
    }

    const std::vector<PrefixRec>& entries() const { return entries_; }
    size_t size() const { return entries_.size(); }

private:
    struct Node {
        int32_t entry = -1;      // index into entries_, -1 when no prefix here
        uint32_t c[2] = {0, 0};  // 0 means absent (index 0 is the root)
    };

    static uint32_t bit_at(const ip6_t& a, int i) {
        uint64_t w = (i < 64) ? a.hi : a.lo;
        int sh = (i < 64) ? (63 - i) : (127 - i);
        return static_cast<uint32_t>((w >> sh) & 1ULL);
    }

    std::vector<Node> nodes_;
    std::vector<PrefixRec> entries_;
};

#endif // SCAMPTRIE_BASE_H
